config.set(StateBackendOptions.STATE_BACKEND, "rocksdb");
config.set(AUTO_WATERMARK_INTERVAL, Duration.ofMillis(200));
config.set(
CheckpointingOptions.CHECKPOINTS_DIRECTORY, "xxxx");
config.set(ExecutionCheckpointingOptions.CHECKPOINTING_INTERVAL, Duration.ofMillis(10_000));
config.set(ExecutionCheckpointingOptions.EXTERNALIZED_CHECKPOINT, RETAIN_ON_CANCELLATION);
config.setString("state.backend.rocksdb.timer-service.factory", "HEAP");

StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment(config);
env.disableOperatorChaining();
env.setParallelism(2);

StreamTableEnvironment tEnv = StreamTableEnvironment.create(env);

DataStreamSource<Row> source =
env.addSource(
new SourceFunction<Row>() {
private boolean running = true;
private int ts = 1000;
private Random rnd = new Random();

@Override
public void run(SourceContext<Row> ctx) throws Exception {
while (running)

{ Thread.sleep(1); ts += rnd.nextInt(1); ctx.collect( Row.ofKind( RowKind.INSERT, Instant.ofEpochMilli(ts), "USD", rnd.nextInt(300))); ctx.collect( Row.ofKind( RowKind.INSERT, Instant.ofEpochMilli(ts), "CHD", rnd.nextInt(200))); ctx.collect( Row.ofKind( RowKind.INSERT, Instant.ofEpochMilli(ts), "BST", rnd.nextInt(200))); }

}

@Override
public void cancel()

{ running = false; }

},
TypeExtractor.getForObject(
Row.ofKind(RowKind.INSERT, Instant.ofEpochMilli(0), "USD", 1)));
// Create a table from change log stream
Table rateTable =
tEnv.fromDataStream(
source,
Schema.newBuilder()
.column("f0", DataTypes.TIMESTAMP_LTZ(3))
.column("f1", DataTypes.STRING().notNull())
.column("f2", DataTypes.INT().notNull())
.watermark("f0", "f0 - INTERVAL '2' SECONDS")
.primaryKey("f1")
.build())
